// Track sent phones in n8n's own persistent static data instead of
// writing back to the xlsx file (avoids the Docker Desktop bind-mount
// write bug entirely). This map survives across runs/restarts as long
// as the n8n_data volume isn't deleted.
const staticData = $getWorkflowStaticData('global');
if (!staticData.sentPhones) staticData.sentPhones = {};

const allRows = items.map(item => item.json);
const unsent = allRows.filter(row => !staticData.sentPhones[row.phone]);

return unsent.map(row => ({ json: row }));

const row = $json;

// Format phone for open-wa: needs '<countrycode><number>@c.us'
// Numbers are already stored as 966XXXXXXXXX with no plus sign.
const chatId = `${row.phone}@c.us`;

// Reuse the same Arabic template your dashboard used.
const message = `السلام عليكم، شفت إعلانك "${row.ad}" في حراج، ياليت نتواصل بخصوص السعر والتفاصيل. وفقك الله.`;

return [{
  json: {
    ...row,
    chatId,
    message
  }
}];

// Mark this phone as done in persistent static data — no file write.
const staticData = $getWorkflowStaticData('global');
if (!staticData.sentPhones) staticData.sentPhones = {};

const phone = $('Prepare Message').item.json.phone;
staticData.sentPhones[phone] = { sent_at: new Date().toISOString() };

return [{ json: $('Prepare Message').item.json }];

// Track failures per phone. Leave it out of sentPhones so a later
// re-run of this workflow retries it. After 3 total failures across
// runs, give up on it so one bad number can't block the queue.
const staticData = $getWorkflowStaticData('global');
if (!staticData.sentPhones) staticData.sentPhones = {};
if (!staticData.failCounts) staticData.failCounts = {};

const phone = $('Prepare Message').item.json.phone;
const errorMessage = $json.error?.message || 'unknown error';

staticData.failCounts[phone] = (staticData.failCounts[phone] || 0) + 1;

const MAX_RETRIES = 3;
let gaveUp = false;
if (staticData.failCounts[phone] >= MAX_RETRIES) {
  staticData.sentPhones[phone] = { sent_at: new Date().toISOString(), gaveUpAfterError: errorMessage };
  gaveUp = true;
}

return [{ json: { ...$('Prepare Message').item.json, error: errorMessage, attempt: staticData.failCounts[phone], gaveUp } }];
